{
  "title": "The Mirror-Bridge Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "A collapsed stone archway with rusted iron gates hanging crookedly, the glass diver standing before them, helmet reflecting the shattered towers beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara studies her map under a flickering lamp.",
      "visual_description": "Mara the cartographer kneels on a pile of rubble, ink-stained fingers tracing a torn parchment map, the oracle lamp beside her casting a single fiery eye across the paper.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scampers ahead into a cursed tower.",
      "visual_description": "A spiral staircase of cracked stone, cobwebs draped like banners; the small metal fox climbs, key-wind tail ticking, blue eyes scanning a glimmering door at the top.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The oracle lamp warns of a trap behind the banner.",
      "visual_description": "An old royal banner hangs from a broken balcony; the lamp's flame flickers as it speaks, its eye narrowing toward a shadowy alcove where a pressure plate hides.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver swims through a window into the throne room.",
      "visual_description": "A shattered stained-glass window reflects the diver's coat as they pass through like water, landing softly on a marble floor littered with fallen chandeliers.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara avoids a patrol by ducking behind a statue.",
      "visual_description": "A stone statue of a forgotten figure, Mara pressed against its base, her compass glowing faintly as heavy footsteps echo from a side corridor.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The sleeping tax collector blocks the treasury door.",
      "visual_description": "A heavy oak door with brass hinges; the sleeping tax collector snores, head on a ledger, stamped papers stuck to his sleeves, barring entry.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox activates a magic door with its tail key.",
      "visual_description": "A stone door carved with runes; the tin fox inserts its wind-up tail into a keyhole, turning it slowly as blue light pulses along the cracks.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp illuminates a hidden passage behind a tapestry.",
      "visual_description": "A moth-eaten tapestry of a battle scene; the lamp's glow reveals a seam, pulling it aside to show a narrow, dusty corridor.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara and the glass diver find a frightened family in a cellar.",
      "visual_description": "A damp cellar with broken barrels; a family of three huddles in the corner, their faces lit by the diver's coat, Mara kneeling to reassure them.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector wakes and demands a bribe.",
      "visual_description": "The tax collector yawns, rubbing his eyes, holding out a stamp-covered hand; a pile of coins and trinkets sits on a crate beside him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox locates a key in a collapsed bell tower.",
      "visual_description": "A bell tower with a fallen bell; the tin fox digs through rubble with its paws, uncovering a brass key among broken timbers.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp warns of a false door that leads to a pit.",
      "visual_description": "A grand door with golden handles; the lamp's eye glows red, its flame sputtering as it gestures toward a faint crack in the floor ahead.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Mara draws a shortcut on her map using the lamp's light.",
      "visual_description": "Mara sits on a fallen pillar, ink pot balanced on her knee, the lamp held above; she sketches a new route through a collapsed wing of the palace.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver and the family pass through a mirror portal.",
      "visual_description": "A large cracked mirror in a hallway; the diver steps through first, and the family follows, their reflections rippling as they emerge on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The tin fox triggers a collapsing ceiling.",
      "visual_description": "A corridor with loose stones; the tin fox steps on a tile, and chunks of ceiling fall behind it, blocking the patrol's path.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The oracle lamp guides the group to the bridge exit.",
      "visual_description": "A stone bridge spanning a dry moat, the lamp's flame burning bright, its eye fixed on the far gate as the group hurries across.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they escape.",
      "visual_description": "The bridge cracks and crumbles into the moat, the group on the far side, the ruined city behind them; the lamp's eye dims as dawn breaks.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

